content.arguments:
{"description":"List target directory tree and file sizes","command":"$root='./'
if(!(Test-Path $root)){ "MISSING ROOT"; exit 1 }
Get-ChildItem -LiteralPath $root -Recurse -File | ForEach-Object { "{0}`t{1}" -f ($_.FullName.Substring($root.Length+1)), $_.Length }
"---"
"fileCount=" + (Get-ChildItem -LiteralPath $root -Recurse -File).Count
"totalBytes=" + ((Get-ChildItem -LiteralPath $root -Recurse -File | Measure-Object -Property Length -Sum).Sum)"}

