content.arguments:
{"command":"$root='./'
$kws=@('用户','用户','账号标识','./','./','./','./')
$files=Get-ChildItem -LiteralPath $root -Recurse -File
foreach($k in $kws){
  $n=0
  foreach($f in $files){
    $n += ([regex]::Matches((Get-Content -LiteralPath $f.FullName -Raw), [regex]::Escape($k))).Count
  }
  "{0} = {1}" -f $k,$n
}","description":"Literal keyword privacy scan across all files"}

